import pyomo.environ as pyo

DATA = {
    "commodities": ["steel", "engines", "electronics", "plastics"],
    "price": {
        "steel": 500,
        "engines": 1500,
        "electronics": 300,
        "plastics": 1200,
    },
    # Labor requirement expressed in person-years per unit
    # (person-months converted using months_per_year)
    "labor_months_per_unit": {
        "steel": 6,
        "engines": 0,      # engines use person-years, handled separately
        "electronics": 6,
        "plastics": 0,     # plastics use person-years, handled separately
    },
    "labor_years_per_unit": {
        "steel": 0,
        "engines": 1,
        "electronics": 0,
        "plastics": 2,
    },
    "months_per_year": 12,
    "labor_available_person_years": 830000,
    "production_cap": {
        "engines": 650000,
        "plastics": 60000,
    },
}

def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.COMMODITIES = pyo.Set(initialize=d["commodities"])

    # Production quantity of each commodity (continuous, non-negative)
    model.production = pyo.Var(
        model.COMMODITIES,
        domain=pyo.NonNegativeReals,
    )

    # Objective: maximize gross domestic product (value of output at world prices)
    def obj_rule(m):
        return sum(d["price"][c] * m.production[c] for c in m.COMMODITIES)
    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Labor constraint: total person-years used <= available
    def labor_rule(m):
        return sum(
            (d["labor_months_per_unit"][c] / d["months_per_year"]
             + d["labor_years_per_unit"][c]) * m.production[c]
            for c in m.COMMODITIES
        ) <= d["labor_available_person_years"]
    model.labor_constraint = pyo.Constraint(rule=labor_rule)

    # Production caps for engines and plastics
    def cap_rule(m, c):
        return m.production[c] <= d["production_cap"][c]
    model.production_cap_constraint = pyo.Constraint(
        pyo.Set(initialize=list(d["production_cap"].keys())),
        rule=cap_rule,
    )

    return model

