import pyomo.environ as pyo

DATA = {
    # Index labels
    "goods": ["steel", "engines", "electronics", "plastics"],

    # World market prices in Klunz
    "price": {
        "steel": 500,
        "engines": 1500,
        "electronics": 300,
        "plastics": 1200,
    },

    # Intermediate input requirements a[j][i] = units of good j per unit of good i
    "intermediate": {
        "steel":       {"steel": 0.0,  "engines": 0.8,  "electronics": 0.01, "plastics": 0.2},
        "engines":     {"steel": 0.02, "engines": 0.0,  "electronics": 0.01, "plastics": 0.03},
        "electronics": {"steel": 0.0,  "engines": 0.15, "electronics": 0.0,  "plastics": 0.05},
        "plastics":    {"steel": 0.01, "engines": 0.11, "electronics": 0.05, "plastics": 0.0},
    },

    # Labour coefficients in person-years per unit of gross output
    "labour": {
        "steel": 6.0 / 12.0,   # 6 person-months
        "engines": 1.0,        # 1 person-year
        "electronics": 6.0 / 12.0,
        "plastics": 2.0,
    },

    # Imported goods cost in Klunz per unit of output
    "imported": {
        "steel": 250,
        "engines": 300,
        "electronics": 50,
        "plastics": 300,
    },

    # Production limits
    "max_output": {
        "steel": None,
        "engines": 650000,
        "electronics": None,
        "plastics": 60000,
    },

    # Total labour available in person-years per year
    "labour_available": 830000,
}


def build_model(data=None):
    d = data or DATA
    goods = d["goods"]

    model = pyo.ConcreteModel()

    model.GOODS = pyo.Set(initialize=goods)

    # Gross output of each good
    def x_bounds(m, j):
        ub = d["max_output"].get(j, None)
        if ub is None:
            return (0, None)
        return (0, ub)

    model.x = pyo.Var(model.GOODS, domain=pyo.NonNegativeReals,
                      bounds=lambda m, j: x_bounds(m, j))

    # Final output / exports of each good
    model.f = pyo.Var(model.GOODS, domain=pyo.NonNegativeReals)

    # Objective: maximize value of final output = GDP
    def obj_rule(m):
        return sum(d["price"][j] * m.f[j] for j in m.GOODS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Material balance for each good:
    # output = final use + intermediate use by all sectors
    def balance_rule(m, j):
        return m.x[j] == m.f[j] + sum(
            d["intermediate"][j][i] * m.x[i] for i in m.GOODS
        )

    model.balance = pyo.Constraint(model.GOODS, rule=balance_rule)

    # Labour availability constraint
    def labour_rule(m):
        return sum(d["labour"][j] * m.x[j] for j in m.GOODS) <= d["labour_available"]

    model.labour = pyo.Constraint(rule=labour_rule)

    # Explicit production limits for engines and plastics
    if d["max_output"].get("engines") is not None:
        def engines_limit_rule(m):
            return m.x["engines"] <= d["max_output"]["engines"]

        model.engines_limit = pyo.Constraint(rule=engines_limit_rule)

    if d["max_output"].get("plastics") is not None:
        def plastics_limit_rule(m):
            return m.x["plastics"] <= d["max_output"]["plastics"]

        model.plastics_limit = pyo.Constraint(rule=plastics_limit_rule)

    return model
